"""Small offline audit core for common GitHub Actions findings."""
import re

LEVEL = {"Low": 0, "Medium": 1, "High": 2}

def _finding(rule, desc, severity, confidence, path, annotation, route, line, col, endcol, feature, kind="Primary"):
    return {"ident": rule, "desc": desc, "url": f"https://docs.zizmor.sh/audits/#{rule}",
      "determinations": {"confidence": confidence, "severity": severity, "persona": "Regular"},
      "locations": [{"symbolic": {"key": {"Local": {"prefix": None, "given_path": path}}, "annotation": annotation,
        "route": {"route": [{"Key": x} if isinstance(x,str) else {"Index": x} for x in route]}, "feature_kind": "Normal", "kind": kind},
        "concrete": {"location": {"start_point": {"row": line-1,"column": col}, "end_point": {"row": line-1,"column": endcol}, "offset_span": {"start": 0,"end": 0}}, "feature": feature, "comments": []}}], "ignored": False}

def audit_text(text, path):
    """Return common findings from workflow text. Coordinates are zero based internally."""
    findings=[]
    lines=text.splitlines()
    for i,line in enumerate(lines):
        m=re.match(r'^(\s*)-\s+uses:\s*["\']?([^\s"\']+)',line)
        if m:
            ref=m.group(2); indent=m.group(1); col=m.start(2)
            # A full 40-character SHA is pinned; local/docker references are not remote actions.
            if "@" in ref and not re.search(r'@[0-9a-fA-F]{40}$',ref):
                findings.append(_finding("unpinned-uses","unpinned action reference","High","High",path,
                  "action is not pinned to a hash (required by blanket policy)", ["jobs", _job(lines,i), "steps", _step_index(lines,i), "uses"], i+1,col,col+len(ref),ref))
            if ref.startswith("actions/checkout@"):
                block="\n".join(lines[i+1:i+5])
                if "persist-credentials: false" not in block:
                    findings.append(_finding("artipacked","credential persistence through GitHub Actions artifacts","Medium","Low",path,
                      "does not set persist-credentials: false", ["jobs",_job(lines,i),"steps",_step_index(lines,i)], i+1,col-len("uses: "),len(line.rstrip()),line.strip()))
        if "${{" in line and "run:" in line:
            expression=re.search(r'\$\{\{\s*([^}]+?)\s*\}\}',line)
            if expression and re.search(r'(github\.event\.|github\.head_ref|github\.issue\.|github\.pull_request\.)',expression.group(1)):
                runcol=line.find("run:")
                findings.append(_finding("template-injection","code injection via template expansion","High","High",path,
                    "may expand into attacker-controllable code",["jobs",_job(lines,i),"steps",_step_index(lines,i),"run"],i+1,expression.start(1),expression.end(1),expression.group(0)))
    return findings

def _job(lines,i):
    for line in reversed(lines[:i]):
        m=re.match(r'^  ([\w-]+):\s*$',line)
        if m and m.group(1) not in ("jobs",): return m.group(1)
    return "job"

def _step_index(lines,i):
    job=_job(lines,i); start=0
    for n,l in enumerate(lines):
        if re.match(r'^  '+re.escape(job)+r':',l): start=n
    return sum(1 for l in lines[start:i] if re.match(r'^\s{6}-\s',l))
"""CLI startup actions shared with the main analyzer."""
import os
import sys


def handle_special(args):
    """Handle immediate CLI actions; return True if execution is complete."""
    if "--help" in args or "-h" in args:
        try:
            with open(os.path.join(os.path.dirname(__file__), "cli_help.txt"), encoding="utf-8") as f:
                sys.stdout.write(f.read())
        except OSError:
            sys.stdout.write("Static analysis for GitHub Actions\nUsage: executable [OPTIONS] <INPUT>...\n")
        return True
    if "--version" in args or "-V" in args:
        print("zizmor 1.25.2")
        return True
    if "--thanks" in args and len(args) == 1:
        print("zizmor's development is sustained by our generous sponsors:")
        print("🌈 Grafana Labs")
        print("🌈 Kusari")
        return True
    return False

